def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent.

    Uses the same bounds as the writer (:func:`_metadata_bounds`) so a stray or
    unfinished BEGIN — a quoted example, an interrupted write — can never be
    read as the authoritative block: the reader and the writer must agree on
    which block that is, or a reader-only quirk could invent a parent or
    dependency that the writer would never have produced. A body with no
    complete pair reads as having no metadata at all.
    """
    if not body:
        return {}
    bounds = _metadata_bounds(body)
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}
